#!/usr/bin/env bash
# Prints the CREATE TABLE statement for the demo's target table, generated by the LiteLLM version
# in the gateway image, so the table always matches the rows that the callback writes.
# Usage: scripts/create_table.sh [<catalog>.<schema>.<table>]   (default: ZEROBUS_TABLE_NAME from .env)
set -euo pipefail
cd "$(dirname "$0")/.."

TABLE="${1:-}"
if [ -z "$TABLE" ]; then
  TABLE="$(grep -E '^ZEROBUS_TABLE_NAME=' .env | cut -d= -f2-)"
fi

docker compose build -q litellm
docker compose run --rm --no-deps -T litellm python -c \
  "import sys; from litellm.integrations.zerobus.row import create_table_sql; print(create_table_sql(sys.argv[1]))" \
  "$TABLE"
